import concurrent.futures
import json
import os
import random
import re
import sys

import numpy
import torch
from filelock import FileLock
from PIL import Image

from via_logger import TimeMeasure


class NVila:

    def __init__(self, model_path, max_batch_size=None, use_trt=False, **kwargs) -> None:
        self._model = None
        self._max_batch_size = max_batch_size
        self._inflight_req_ids = []
        self._use_trt = use_trt

        if bool(os.environ.get("NVILA_USE_PYTORCH", "")):
            self._use_trt = False

        if self._use_trt:
            # TRT Model
            with TimeMeasure("VILA TRT model load"):
                # Load the TRT model
                import tensorrt_llm.bindings
                from tensorrt_llm._torch import LLM

                if "NVILA_VIDEO_MAX_TILES" not in os.environ:
                    os.environ["NVILA_VIDEO_MAX_TILES"] = "4"

                with FileLock(model_path + "/.lock"):
                    self._llm = LLM(
                        model=model_path,
                        kv_cache_config=tensorrt_llm.bindings.executor.KvCacheConfig(
                            free_gpu_memory_fraction=float(
                                os.environ.get("TRT_LLM_MEM_USAGE_FRACTION", "") or 0.4
                            )
                        ),
                    )
        else:
            sys.path.append(os.path.dirname(__file__) + "/VILA")
            import llava
            from llava import conversation as clib

            self._model = llava.load(model_path)
            clib.default_conversation = clib.conv_templates["auto"].copy()
            if os.environ.get("NVILA_VIDEO_MAX_TILES"):
                self._model.config.video_max_tiles = int(os.environ.get("NVILA_VIDEO_MAX_TILES"))
                self._model.llm.config.video_max_tiles = int(
                    os.environ.get("NVILA_VIDEO_MAX_TILES")
                )

        self._output_tpool = concurrent.futures.ThreadPoolExecutor(max_workers=max_batch_size)

        self.model_path = model_path

        with open(os.path.join(model_path, "config.json"), "r") as f:
            self._model_config = json.load(f)
            self._num_time_tokens = self._model_config.get("num_time_tokens", 0)

    @property
    def model_name(self):
        return self._model_name

    def get_conv(self):
        return self._conv.copy()

    def _postprocess(self, output, video_frames_times):
        with TimeMeasure("TRT generate"):
            output.result()
            self._inflight_req_ids.remove(output)
        result = output.outputs[0].text
        if video_frames_times:
            for i, t in enumerate(video_frames_times):
                result = re.sub(f"T{i}(?![0-9])", t, result)
                result = re.sub(f"t{i}(?![0-9])", t, result)
                excess_pattern = re.compile(r"<t(\d+)>")
                matches = excess_pattern.findall(result)
                for match in matches:
                    t = int(match)
                    if t >= len(video_frames_times):
                        result = result.replace(f"<t{t}>", f"<{video_frames_times[-1]}>")
        return [result], [{"input_tokens": 0, "output_tokens": output.outputs[0].length}]

    def can_enqueue_requests(self):
        return len(self._inflight_req_ids) < self._max_batch_size

    def warmup(self):
        self.generate("Say Hi", [torch.ones(100, 100, 3).cuda()])

    @property
    def num_time_tokens(self):
        return self._num_time_tokens

    def generate(self, prompt, images, generation_config=None, video_frames_times=None):
        """Generate a response for prompt using the video embeddings

        Args:
            prompt: Conversation prompt
            video_embeds: Batch of video embeddings
            video_frames_times: Batch of video frame times used for embeddings for each chunk
            generation_config: VLM generation config. Defaults to None.

        Returns:
            List of responses for the batch of chunks
        """

        # Populate default values for the VLM generation parameters
        if not generation_config:
            generation_config = {}

        if "temperature" not in generation_config:
            generation_config["temperature"] = 0.4

        if generation_config["temperature"] == 0:
            generation_config.pop("temperature")

        if "max_new_tokens" not in generation_config:
            generation_config["max_new_tokens"] = 512

        if "top_p" not in generation_config:
            generation_config["top_p"] = 1

        if "top_k" not in generation_config:
            generation_config["top_k"] = 100
        generation_config["top_k"] = int(generation_config["top_k"])

        if "seed" in generation_config:
            seed = generation_config["seed"]
            generation_config.pop("seed")
        else:
            seed = 1

        # Set the seed
        random.seed(seed)
        numpy.random.seed(seed)
        torch.manual_seed(seed)
        torch.cuda.manual_seed_all(seed)

        if self._use_trt:

            from tensorrt_llm import SamplingParams

            input = {
                "prompt": "<vila/video>" + prompt,
                "multi_modal_data": {
                    "video": [[torch.permute(image, (2, 0, 1)).half().div(255) for image in images]]
                },
            }

            # TRT mode
            output = self._llm.generate_async(
                inputs=input,
                sampling_params=SamplingParams(
                    max_tokens=generation_config.pop("max_new_tokens"),
                    **generation_config,
                    seed=seed,
                ),
            )

            self._inflight_req_ids.append(output)

            return self._output_tpool.submit(
                self._postprocess,
                output,
                video_frames_times,
            )
        else:
            images = [Image.fromarray(image.cpu().detach().numpy()) for image in images]
            media = {"video": [images]}
            gen_config = self._model.default_generation_config
            gen_config.update(**generation_config)
            result = self._model.generate_content(
                "<vila/video>" + prompt, media=media, generation_config=gen_config
            )
            if video_frames_times:
                for i, t in enumerate(video_frames_times):
                    result = re.sub(f"T{i}(?![0-9])", t, result)
            return [result], [{"input_tokens": 0, "output_tokens": 0}]

    @staticmethod
    def get_model_info():
        return "nvila", "internal", "NVIDIA"

import asyncio
import os
import sys
import tempfile
from typing import List

import pytest
import torch
from transformers import AutoTokenizer

from tensorrt_llm.hlapi.llm import (LLM, ModelConfig, SamplingConfig,
                                    TokenizerBase, TransformersTokenizer)


def get_model_path(model_name):
    sys.path.append(os.path.join(os.path.dirname(__file__), '..'))
    from utils.llm_data import llm_models_root
    return str(llm_models_root() / model_name)


default_model_name = "llama-models/llama-7b-hf"
llama_model_path = get_model_path(default_model_name)
llm_engine_dir = os.environ.get('LLM_ENGINE_DIR', './tmp.engine')
prompts = ["Tell a story", "Who are you"]

cur_dir = os.path.dirname(os.path.abspath(__file__))
models_root = os.path.join(cur_dir, '../../models')


def test_tokenizer():
    tokenizer = TransformersTokenizer.from_pretrained(llama_model_path)

    res = tokenizer("hello world")
    assert res


def test_llm_loadding_from_hf():
    config = ModelConfig(llama_model_path)
    llm = LLM(config)

    for output in llm.generate(prompts):
        print(output)


class MyTokenizer(TokenizerBase):
    ''' A wrapper for the Transformers' tokenizer.
    This is the default tokenizer for LLM. '''

    @classmethod
    def from_pretrained(cls, pretrained_model_dir: str, **kwargs):
        tokenizer = AutoTokenizer.from_pretrained(pretrained_model_dir,
                                                  **kwargs)
        return MyTokenizer(tokenizer)

    def __init__(self, tokenizer):
        self.tokenizer = tokenizer

    @property
    def eos_token_id(self) -> int:
        return self.tokenizer.eos_token_id

    @property
    def pad_token_id(self) -> int:
        return self.tokenizer.pad_token_id

    def encode(self, text: str) -> List[int]:
        return self.tokenizer.encode(text)

    def decode(self, token_ids: List[int]) -> str:
        return self.tokenizer.decode(token_ids)

    def batch_encode_plus(self, texts: List[str]) -> dict:
        return self.tokenizer.batch_encode_plus(texts)


def test_llm_with_customized_tokenizer():
    config = ModelConfig(llama_model_path)
    llm = LLM(
        config,
        # a customized tokenizer is passed to override the default one
        tokenizer=MyTokenizer.from_pretrained(config.model_dir))

    for output in llm.generate(prompts):
        print(output)


def test_llm_without_tokenizer():
    config = ModelConfig(llama_model_path)
    llm = LLM(
        config,
        # this will turn off tokenizer for pre-processing and post-processing
        enable_tokenizer=False,
    )

    sampling_config = SamplingConfig(end_id=2,
                                     pad_id=2,
                                     output_sequence_lengths=True,
                                     return_dict=True)

    prompts = [[23, 14, 3]]

    for output in llm.generate(prompts, sampling_config=sampling_config):
        print(output)


@pytest.mark.skipif(torch.cuda.device_count() < 2,
                    reason="The test needs at least 2 GPUs, skipping")
@pytest.mark.parametrize("model_name",
                         [default_model_name, "Mixtral-8x7B-v0.1"])
def test_llm_build_engine_for_tp2(model_name):
    config = ModelConfig(get_model_path(model_name))
    config.parallel_config.tp_size = 2
    llm = LLM(config)

    with tempfile.TemporaryDirectory() as tmpdir:
        llm.save(tmpdir)


@pytest.mark.skipif(torch.cuda.device_count() < 2,
                    reason="The test needs at least 2 GPUs, skipping")
@pytest.mark.parametrize("model_name",
                         [default_model_name, "Mixtral-8x7B-v0.1"])
def test_llm_generate_for_tp2(model_name):
    config = ModelConfig(get_model_path(model_name))
    config.parallel_config.tp_size = 2
    llm = LLM(config)
    for output in llm.generate(prompts):
        print(output)


def test_llm_generate_async(model_name=default_model_name, tp_size: int = 1):
    config = ModelConfig(llama_model_path)
    config.parallel_config.tp_size = tp_size
    llm = LLM(
        config,
        async_mode=True,
        # set to 40%, since by default, the executor will occupy all the free memory, making some other tests OOM in CI
        kvcahe_free_gpu_memory_fraction=0.4)

    def test_async(streaming: bool):

        async def task(prompt: str):
            outputs = []
            async for output in llm.generate_async(prompt, streaming=streaming):
                print('output', output)
                outputs.append(output.text)
            print(' '.join(outputs))

        async def main():
            tasks = [task(prompt) for prompt in prompts]
            await asyncio.gather(*tasks)

        asyncio.run(main())

    def test_wait(streaming: bool):
        for prompt in prompts:
            future = llm.generate_async(prompt, streaming=streaming)
            for output in future:
                print('wait', output)

    def test_non_streaming_usage_wait():
        for prompt in prompts:
            output = llm.generate_async(prompt, streaming=False)
            print(output.text)

    def test_future(streaming: bool):
        for prompt in prompts:
            future = llm.generate_async(prompt, streaming=streaming)
            if streaming is True:
                for output in future:
                    # Do something else and then wait for the result if needed
                    output = output.wait_completion(timeout=10)
                    print('future', output.text)
            else:
                # Do something else and then wait for the result if needed
                output = future.wait_completion(timeout=10)
                print('future', output.text)

    test_async(streaming=True)
    test_async(streaming=False)
    test_wait(streaming=True)
    test_wait(streaming=False)
    test_future(streaming=True)
    test_future(streaming=False)
    test_non_streaming_usage_wait()


@pytest.mark.skipif(torch.cuda.device_count() < 2,
                    reason="The test needs at least 2 GPUs, skipping")
@pytest.mark.parametrize("model_name",
                         [default_model_name, "Mixtral-8x7B-v0.1"])
def test_llm_generate_async_tp2(model_name):
    test_llm_generate_async(model_name, tp_size=2)


# TODO[chunweiy]: Add test for loading inmemory model
if __name__ == '__main__':
    test_llm_generate_async_tp2(default_model_name)

