from tensorrt_llm.plugin import PluginConfig
from tensorrt_llm.plugin.plugin import ContextFMHAType
from transformers import AutoConfig

from optimum.nvidia.lang import DataType
from optimum.nvidia.utils.nvml import is_post_hopper
from optimum.utils import NormalizedConfig


if TYPE_CHECKING:
    from transformers import PretrainedConfig

INFER_NUM_LOCAL_GPUS = -1
LOGGER = getLogger()


@dataclass
class ExportConfig:
    dtype: str
    max_input_len: int
    max_output_len: int
    max_batch_size: int

    # Optional parameters
    max_beam_width: int = 1
    max_num_tokens: int = -1
    enabled_chunked_context: int = False

    sharding: Optional[ShardingInfo] = None

    optimization_level: int = 3

    def __post_init__(self):
        if self.max_batch_size < 1:
            raise ValueError(f"max_batch_size should >= 1, got {self.max_batch_size}")

    @staticmethod
    def from_pretrained(
        model_id_or_path: Union[str, PathLike], max_batch_size: int = 1
    ) -> "ExportConfig":
        return ExportConfig.from_config(
            AutoConfig.from_pretrained(model_id_or_path), max_batch_size
        )

    @staticmethod
    def from_config(
        config: Union[NormalizedConfig, "PretrainedConfig"], max_batch_size: int = 1
    ) -> "ExportConfig":
        if not isinstance(config, NormalizedConfig):
            config = NormalizedConfig(config)

        dtype = DataType.from_torch(config.torch_dtype).value
        max_input_len = config.max_position_embeddings
        max_output_len = config.max_position_embeddings

        econfig = ExportConfig(
            dtype=dtype,
            max_input_len=max_input_len,
            max_output_len=max_output_len,
            max_batch_size=max_batch_size,
        )

        # Initialize sharing information with single shard
        econfig.with_sharding()
        econfig.validate()
        return econfig

    def validate(self) -> "ExportConfig":
        if self.optimization_level < 0:
            raise ValueError(
                f"optimization_level should be >= 0, got {self.optimization_level}"
            )

        if self.max_num_tokens == -1:
            if self.enabled_chunked_context:
                # Should be N * tokens_per_block (8192 is the default)
                self.max_num_tokens = 8192  # hardcode for now
                warn(
                    f"max_num_tokens set to {self.max_num_tokens} with chunked context enabled might not be optimal."
                )
            else:
                self.max_num_tokens = self.max_batch_size * self.max_input_len // 2

            LOGGER.debug(f"Inferred max_num_tokens={self.max_num_tokens}")

        return self

    @property
    def plugin_config(self) -> "PluginConfig":
        config = PluginConfig()

        config.gemm_plugin = "auto"
        config.gpt_attention_plugin = "auto"
        config.set_context_fmha(ContextFMHAType.enabled)
        config.enable_paged_kv_cache(32)
        config.use_paged_context_fmha = True

        if self.sharding.world_size > 1:
            config.set_nccl_plugin()

        if DataType(self.dtype) == DataType.FLOAT8:
            config.gemm_swiglu_plugin = True

        return config

    def to_builder_config(
        self,
        qmode: Optional["QuantMode"] = None,
        plugin_config: Optional[PluginConfig] = None,
    ) -> "BuildConfig":
        self.validate()

        plugin_config = plugin_config or self.plugin_config
        plugin_config.multiple_profiles = True
        if qmode:
            plugin_config.use_fp8_context_fmha = (
                qmode.has_fp8_qdq() or qmode.has_fp8_kv_cache()
            )

            # Low latency GeMM plugin is only available for sm90+ and float8 weigths and activations
            if qmode.has_fp8_qdq() and qmode.has_fp8_kv_cache() and is_post_hopper():
                plugin_config.low_latency_gemm_plugin = "fp8"

            if qmode.is_weight_only():
                plugin_config.weight_only_groupwise_quant_matmul_plugin = "auto"
            weight_sparsity = qmode.sparsity is not None
        else:
            weight_sparsity = False

        return BuildConfig(
            max_input_len=self.max_input_len,
            max_seq_len=self.max_output_len,
            max_batch_size=self.max_batch_size,
            max_beam_width=self.max_beam_width,
            max_num_tokens=self.max_num_tokens,
            plugin_config=plugin_config,
            use_fused_mlp=True,
            weight_sparsity=weight_sparsity,
        )

    def with_sharding(
        self,
        tp: int = 1,
        pp: int = 1,
        gpus_per_node: int = 8,
        sharding: Optional[ShardingInfo] = None,
    ) -> "ExportConfig":
        self.sharding = sharding or ShardingInfo(
            tp_size=tp, pp_size=pp, world_size=tp * pp, gpus_per_node=gpus_per_node
        )
        return self


def auto_parallel(
    config: "ExportConfig", world_size: int = INFER_NUM_LOCAL_GPUS
) -> "ExportConfig":
    """
    Helper to infer the most suitable parallelization strategy to apply to the model with respect to the local hardware.
    :param config: `ExportConfig` the quantization process should be added to
    :param world_size: Number of GPUs to consider when discovering automatic parallelization strategies
    :return: `ExportConfig`
    """
    # Infer number of GPUs on the system
    if world_size < 1:
        from optimum.nvidia.utils.nvml import get_device_count

        world_size = get_device_count()

        LOGGER.info(f"Found {world_size} GPUs on the system")

    # Handle all the different cases (0, 1, N > 1)
    if world_size == 0:
        raise ValueError("No GPU found")
    elif world_size == 1:
        return config.with_sharding(tp=1, pp=1, gpus_per_node=world_size)
    else:
        LOGGER.info(f"Creating auto-parallelization strategy on {world_size}-GPUs")
        LOGGER.warning(
            "Auto-parallelization strategy is currently in beta and might not be optimal"
        )

        if world_size == 2:
            return config.with_sharding(tp=2, pp=1, gpus_per_node=world_size)
        elif world_size == 4:
            return config.with_sharding(tp=2, pp=2, gpus_per_node=world_size)
        elif world_size == 8:
            return config.with_sharding(tp=4, pp=2, gpus_per_node=world_size)
        else:
            raise ValueError(
                f"Unsupported number of GPUs: {world_size}. "
                "Please open-up and issue on the optimum-nvidia repository: "
                "https://github.com/huggingface/optimum-nvidia"
            )


def sharded(config: "ExportConfig", tp: int = 1, pp: int = 1) -> "ExportConfig":
    """
    Helper to specific the parallelization strategy to apply to the model
    :param config: `ExportConfig` the quantization process should be added to
    :param tp: Tensor Parallelism degree to apply (`int` >= 1)
    :param pp: Pipeline Parallelism degree to apply (`int` >= 1)
    :return: `ExportConfig`
    """
    if tp < 1:
        raise ValueError(f"Tensor Parallelism (tp) should be >= 1 (got: tp={tp})")

    if pp < 1:
        raise ValueError(f"Pipeline Parallelism (pp) should be >= 1 (got: pp={pp})")

    return config.with_sharding(
        sharding=ShardingInfo(tp_size=tp, pp_size=pp, world_size=tp * pp)
    )

#!/usr/bin/env python3
import os
from typing import Optional

import click

from tensorrt_llm._tensorrt_engine import LLM as TrtLLM
from tensorrt_llm.llmapi import LLM, BuildConfig, SamplingParams


@click.command()
@click.option("--model_dir", type=str, required=True)
@click.option("--tp_size", type=int, default=1)
@click.option("--engine_dir", type=str, default=None)
@click.option("--backend", type=str, default=None)
def main(model_dir: str, tp_size: int, engine_dir: str, backend: Optional[str]):
    build_config = BuildConfig()
    build_config.max_batch_size = 8
    build_config.max_input_len = 256
    build_config.max_seq_len = 512

    backend = backend or "tensorrt"
    assert backend in ["pytorch", "tensorrt"]

    llm_cls = TrtLLM if backend == "tensorrt" else LLM

    kwargs = {} if backend == "pytorch" else {"build_config": build_config}

    llm = llm_cls(model_dir, tensor_parallel_size=tp_size, **kwargs)

    if engine_dir is not None and os.path.abspath(
            engine_dir) != os.path.abspath(model_dir):
        llm.save(engine_dir)

    sampling_params = SamplingParams(max_tokens=10, end_id=-1)

    prompt_token_ids = [45, 12, 13]
    for output in llm.generate([prompt_token_ids],
                               sampling_params=sampling_params):
        print(output)


if __name__ == '__main__':
    main()

import asyncio
import os
import sys
import tempfile
from typing import List

import pytest
import torch
from transformers import AutoTokenizer

from tensorrt_llm.hlapi.llm import (LLM, ModelConfig, SamplingConfig,
                                    TokenizerBase, TransformersTokenizer)


def get_model_path(model_name):
    sys.path.append(os.path.join(os.path.dirname(__file__), '..'))
    from utils.llm_data import llm_models_root
    return str(llm_models_root() / model_name)


default_model_name = "llama-models/llama-7b-hf"
llama_model_path = get_model_path(default_model_name)
llm_engine_dir = os.environ.get('LLM_ENGINE_DIR', './tmp.engine')
prompts = ["Tell a story", "Who are you"]

cur_dir = os.path.dirname(os.path.abspath(__file__))
models_root = os.path.join(cur_dir, '../../models')


def test_tokenizer():
    tokenizer = TransformersTokenizer.from_pretrained(llama_model_path)

    res = tokenizer("hello world")
    assert res


def test_llm_loadding_from_hf():
    config = ModelConfig(llama_model_path)
    llm = LLM(config)

    for output in llm.generate(prompts):
        print(output)


class MyTokenizer(TokenizerBase):
    ''' A wrapper for the Transformers' tokenizer.
    This is the default tokenizer for LLM. '''

    @classmethod
    def from_pretrained(cls, pretrained_model_dir: str, **kwargs):
        tokenizer = AutoTokenizer.from_pretrained(pretrained_model_dir,
                                                  **kwargs)
        return MyTokenizer(tokenizer)

    def __init__(self, tokenizer):
        self.tokenizer = tokenizer

    @property
    def eos_token_id(self) -> int:
        return self.tokenizer.eos_token_id

    @property
    def pad_token_id(self) -> int:
        return self.tokenizer.pad_token_id

    def encode(self, text: str) -> List[int]:
        return self.tokenizer.encode(text)

    def decode(self, token_ids: List[int]) -> str:
        return self.tokenizer.decode(token_ids)

    def batch_encode_plus(self, texts: List[str]) -> dict:
        return self.tokenizer.batch_encode_plus(texts)


def test_llm_with_customized_tokenizer():
    config = ModelConfig(llama_model_path)
    llm = LLM(
        config,
        # a customized tokenizer is passed to override the default one
        tokenizer=MyTokenizer.from_pretrained(config.model_dir))

    for output in llm.generate(prompts):
        print(output)


def test_llm_without_tokenizer():
    config = ModelConfig(llama_model_path)
    llm = LLM(
        config,
        # this will turn off tokenizer for pre-processing and post-processing
        enable_tokenizer=False,
    )

    sampling_config = SamplingConfig(end_id=2,
                                     pad_id=2,
                                     output_sequence_lengths=True,
                                     return_dict=True)

    prompts = [[23, 14, 3]]

    for output in llm.generate(prompts, sampling_config=sampling_config):
        print(output)


@pytest.mark.skipif(torch.cuda.device_count() < 2,
                    reason="The test needs at least 2 GPUs, skipping")
@pytest.mark.parametrize("model_name",
                         [default_model_name, "Mixtral-8x7B-v0.1"])
def test_llm_build_engine_for_tp2(model_name):
    config = ModelConfig(get_model_path(model_name))
    config.parallel_config.tp_size = 2
    llm = LLM(config)

    with tempfile.TemporaryDirectory() as tmpdir:
        llm.save(tmpdir)


@pytest.mark.skipif(torch.cuda.device_count() < 2,
                    reason="The test needs at least 2 GPUs, skipping")
@pytest.mark.parametrize("model_name",
                         [default_model_name, "Mixtral-8x7B-v0.1"])
def test_llm_generate_for_tp2(model_name):
    config = ModelConfig(get_model_path(model_name))
    config.parallel_config.tp_size = 2
    llm = LLM(config)
    for output in llm.generate(prompts):
        print(output)


def test_llm_generate_async(model_name=default_model_name, tp_size: int = 1):
    config = ModelConfig(llama_model_path)
    config.parallel_config.tp_size = tp_size
    llm = LLM(
        config,
        async_mode=True,
        # set to 40%, since by default, the executor will occupy all the free memory, making some other tests OOM in CI
        kvcahe_free_gpu_memory_fraction=0.4)

    def test_async(streaming: bool):

        async def task(prompt: str):
            outputs = []
            async for output in llm.generate_async(prompt, streaming=streaming):
                print('output', output)
                outputs.append(output.text)
            print(' '.join(outputs))

        async def main():
            tasks = [task(prompt) for prompt in prompts]
            await asyncio.gather(*tasks)

        asyncio.run(main())

    def test_wait(streaming: bool):
        for prompt in prompts:
            future = llm.generate_async(prompt, streaming=streaming)
            for output in future:
                print('wait', output)

    def test_non_streaming_usage_wait():
        for prompt in prompts:
            output = llm.generate_async(prompt, streaming=False)
            print(output.text)

    def test_future(streaming: bool):
        for prompt in prompts:
            future = llm.generate_async(prompt, streaming=streaming)
            if streaming is True:
                for output in future:
                    # Do something else and then wait for the result if needed
                    output = output.wait_completion(timeout=10)
                    print('future', output.text)
            else:
                # Do something else and then wait for the result if needed
                output = future.wait_completion(timeout=10)
                print('future', output.text)

    test_async(streaming=True)
    test_async(streaming=False)
    test_wait(streaming=True)
    test_wait(streaming=False)
    test_future(streaming=True)
    test_future(streaming=False)
    test_non_streaming_usage_wait()


@pytest.mark.skipif(torch.cuda.device_count() < 2,
                    reason="The test needs at least 2 GPUs, skipping")
@pytest.mark.parametrize("model_name",
                         [default_model_name, "Mixtral-8x7B-v0.1"])
def test_llm_generate_async_tp2(model_name):
    test_llm_generate_async(model_name, tp_size=2)


# TODO[chunweiy]: Add test for loading inmemory model
if __name__ == '__main__':
    test_llm_generate_async_tp2(default_model_name)

